{"results": [{"id": "hp_doc_db5f416caf488c057ef39c7e044f99e90f9f820130be129cd5f10883a0277256", "title": "My First Wedding (2006 film)", "text": "A young lady (Rachael Leigh Cook) about to get married realizes that she has a problem: she fantasizes about every man she sees. She goes to confess at church but unknowingly confesses to a young man (Kenny Doughty) who is not a priest. He agrees to help her, but falls in love with her along the way. Unfortunately she still thinks he is a priest.", "score": 22.9741}, {"id": "hp_doc_fbf7f88c7efef22d695a56b2140e0f335f5e4c568cf2978297439b0a0464050c", "title": "My First Wedding (2011 film)", "text": "My First Wedding (Spanish: Mi primera boda ) is a 2011 Argentine comedy film directed by Ariel Winograd.", "score": 20.1982}, {"id": "hp_doc_8a528291058115428a61351dc0317b1d82c0c5b416336676f43277011f6b962c", "title": "Harlee McBride", "text": "Harlee McBride (born November 20, 1948) is an American actress. She is best known for the role of Cynthia Chatterley in \"Young Lady Chatterley\" and \"Young Lady Chatterley II\".", "score": 19.6255}], "remaining_searches": 2}
